import{z as s,x as e,o as B,c as i,q as A,j as t,D as a,d as n,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Poisson 与负二项良率模型","description":"","frontmatter":{"title":"Poisson 与负二项良率模型","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/yield-models.md","filePath":"litho/yield-models.md","lastUpdated":1791063341000}'),C={name:"litho/yield-models.md"};function D(F,E,p,d,h,P){const o=e("Mermaid");return B(),i("div",null,[E[1]||(E[1]=A('<h1 id="poisson-与负二项良率模型" tabindex="-1">Poisson 与负二项良率模型 <a class="header-anchor" href="#poisson-与负二项良率模型" aria-label="Permalink to &quot;Poisson 与负二项良率模型&quot;">​</a></h1><div class="epigraph"><p>良率先是一张缺陷密度的概率：Poisson 假定管芯间独立均匀；簇生和晶圆间不齐用负二项把方差撑开。</p><footer>—— 对照 Stapper 对 IC 良率与负二项的经典工作；半导体良率模型教材通称</footer></div><p><a href="/litho/virtual-metrology">上一课</a>结束控制环。缺口是出货概率：缺陷如何把管芯杀死。光刻主干已多次点名随机与系统失效；本课钉经典良率函数。关键面积如何把布局变成有效缺陷灵敏度，留给<a href="/litho/critical-area">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Poisson 模型：\\(Y = e^{-DA}\\)，\\(D\\) 缺陷密度，\\(A\\) 有效面积。它低估实际良率时，往往是因为缺陷簇生（一次颗粒打一簇管芯）或 \\(D\\) 在晶圆间波动。负二项（Murphy、Seeds、Stapper 等形式）引入聚类参数，同样平均 \\(D\\) 下良率更高——因为缺陷挤在少数管芯上。</p><p>缺口是<strong>模型是计数统计，不是工艺物理</strong>。把 Poisson 倒过来估 \\(D\\)，再当光刻缺陷密度去拧剂量，会把系统热点当成随机颗粒。下一课关键面积、再下一课系统对随机，就是为了拆开。</p><h3 id="大管芯更疼" tabindex="-1">大管芯更疼 <a class="header-anchor" href="#大管芯更疼" aria-label="Permalink to &quot;大管芯更疼&quot;">​</a></h3><p>同一 \\(D\\)，面积翻倍，Poisson 良率指数下降。这是芯片尺寸与缺陷密度的第一课，也是为何边缘部分场的管芯统计要分开：它们的有效 \\(A\\) 和 \\(D\\) 都不同。</p><p><span class="marginnote">数字实例：\\(D=0.5\\)（每平方厘米 0.5 个）、\\(A=1\\) 平方厘米时，期望缺陷 0.5 个，Poisson 给出 \\(Y=e^{-0.5}\\approx 61\\%\\)。若这 0.5 个其实是簇生、总挤在少数管芯上，多数管芯会完全干净，真实良率反而更高——这正是负二项比 Poisson 乐观的原因。</span></p><p><span class="marginnote">拟合聚类参数需要足够失败管芯。良率 99% 时，负二项与 Poisson 在工程上难分，却会在下一节点面积增大时分叉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：探针图、缺陷检测计数（需复检课校正）。拟合：Poisson 对负二项，看残差是否空间相关——相关则系统或簇生。分层：按层、按缺陷类型。与控制：APC 不直接进 \\(Y\\) 公式；良率模型吃的是缺陷与参数分布。</p><p><span class="marginnote">常见误区：把模型倒推出来的 \\(D\\) 当成光刻缺陷密度，直接拿去拧剂量。这个 \\(D\\) 是把颗粒、桥连、系统热点全部平均后的「等效数」，热点混在里面；拿它调扫描机，等于把别人的账算到自己头上。</span></p><p>拟合前先做系统叠图。空间相关强时，先拆系统账，再对残差拟合 \\(D\\)。</p>',14)),(B(),t(l,null,{default:a(()=>[r(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E6%8E%A2%E9%92%88%E5%9B%BE%20%2B%20%E7%BC%BA%E9%99%B7%E6%A3%80%E6%B5%8B%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20OV%5B%22%E7%B3%BB%E7%BB%9F%E5%8F%A0%E5%9B%BE%EF%BC%9A%E6%AE%8B%E5%B7%AE%E6%98%AF%E5%90%A6%E7%A9%BA%E9%97%B4%E7%9B%B8%E5%85%B3%22%5D%0A%20%20OV%20--%3E%7C%22%E5%BC%BA%E7%9B%B8%E5%85%B3%22%7C%20SYS%5B%22%E5%85%88%E6%8B%86%E7%B3%BB%E7%BB%9F%E8%B4%A6%22%5D%0A%20%20OV%20--%3E%7C%22%E4%B8%8D%E7%9B%B8%E5%85%B3%22%7C%20POI%5B%22%E7%9B%B4%E6%8E%A5%E6%8B%9F%E5%90%88%20Poisson%22%5D%0A%20%20SYS%20--%3E%20NB%5B%22%E6%AE%8B%E5%B7%AE%E6%8B%9F%E5%90%88%E8%B4%9F%E4%BA%8C%E9%A1%B9%EF%BC%9A%E4%BC%B0%E8%81%9A%E7%B1%BB%E5%8F%82%E6%95%B0%22%5D%0A%20%20POI%20--%3E%20ACC%5B%22%E5%80%92%E6%8E%A8%E7%9A%84%20D%20%E5%8F%AA%E8%BF%9B%E8%89%AF%E7%8E%87%E8%B4%A6%22%5D%0A%20%20NB%20--%3E%20ACC%0A%60%60%60Stapper%20%E7%9A%84%E8%B4%9F%E4%BA%8C%E9%A1%B9%E5%A4%84%E7%90%86%E7%9A%84%E6%98%AF%E9%9A%8F%E6%9C%BA%E7%B0%87%E7%94%9F%EF%BC%8C%E4%B8%8D%E6%98%AF%E6%8A%8A%20OPC%20%E7%83%AD%E7%82%B9%E5%B9%B3%E5%9D%87%E8%BF%9B%E8%81%9A%E7%B1%BB%E5%8F%82%E6%95%B0%E3%80%82%0A%0A%23%23%20%E6%9C%BA%E5%88%B6%0A%0APoisson%20%E6%9D%A5%E8%87%AA%E7%A8%80%E6%9C%89%E7%8B%AC%E7%AB%8B%E4%BA%8B%E4%BB%B6%E3%80%82%E8%B4%9F%E4%BA%8C%E9%A1%B9%E5%8F%AF%E7%90%86%E8%A7%A3%E4%B8%BA%20Gamma%20%E6%B7%B7%E5%90%88%E7%9A%84%20Poisson%EF%BC%88%24D%24%20%E9%9A%8F%E6%9C%BA%EF%BC%89%E3%80%82%E7%A9%BA%E9%97%B4%E4%B8%8A%EF%BC%8C%E7%B0%87%E7%94%9F%E9%80%A0%E6%88%90%E7%9B%B8%E9%82%BB%E7%AE%A1%E8%8A%AF%E5%90%8C%E6%AD%BB%E3%80%82%E5%9B%BE%E5%BD%A2%E5%8C%96%E9%9A%8F%E6%9C%BA%EF%BC%88%E7%BC%BA%E5%AD%94%EF%BC%89%E6%9B%B4%E6%8E%A5%E8%BF%91%E7%8B%AC%E7%AB%8B%20Bernoulli%EF%BC%8C%E7%94%A8%20Poisson%20%E9%9D%A2%E7%A7%AF%E8%A6%81%E6%8D%A2%E6%88%90%E3%80%8C%E6%AF%8F%E5%AD%94%E5%A4%B1%E8%B4%A5%E7%8E%87%20%C3%97%20%E5%AD%94%E6%95%B0%E3%80%8D%EF%BC%8C%E4%B8%8D%E6%98%AF%E9%A2%97%E7%B2%92%20%24DA%24%E2%80%94%E2%80%94%E9%9A%8F%E6%9C%BA%E8%89%AF%E7%8E%87%E8%AF%BE%E5%86%8D%E5%86%99%E3%80%82%0A%0A%3Cspan%20class%3D%22marginnote%22%3E%E3%80%8CGamma%20%E6%B7%B7%E5%90%88%E7%9A%84%20Poisson%E3%80%8D%E5%8F%AF%E4%BB%A5%E7%BF%BB%E8%AF%91%E6%88%90%E4%B8%A4%E6%AD%A5%E6%8E%B7%E9%AA%B0%E5%AD%90%EF%BC%9A%E5%85%88%E7%BB%99%E6%AF%8F%E7%89%87%E6%99%B6%E5%9C%86%E6%8A%BD%E4%B8%80%E4%B8%AA%E5%B1%9E%E4%BA%8E%E8%87%AA%E5%B7%B1%E7%9A%84%E7%BC%BA%E9%99%B7%E5%AF%86%E5%BA%A6%20%24D%24%EF%BC%88%E8%BF%99%E4%B8%80%E6%AD%A5%E6%9C%8D%E4%BB%8E%20Gamma%20%E5%88%86%E5%B8%83%EF%BC%89%EF%BC%8C%E5%86%8D%E5%9C%A8%E8%BF%99%E4%B8%AA%20%24D%24%20%E4%B8%8B%E6%8C%89%20Poisson%20%E6%92%92%E7%BC%BA%E9%99%B7%E3%80%82%E4%B8%A4%E6%AD%A5%E5%8F%A0%E5%8A%A0%E6%92%91%E5%A4%A7%E4%BA%86%E6%96%B9%E5%B7%AE%EF%BC%8C%E7%BC%BA%E9%99%B7%E6%9B%B4%E5%AE%B9%E6%98%93%E3%80%8C%E6%89%8E%E5%A0%86%E3%80%8D%EF%BC%8C%E8%BF%99%E5%B0%B1%E6%98%AF%E8%B4%9F%E4%BA%8C%E9%A1%B9%E7%9A%84%E5%85%A8%E9%83%A8%E6%9D%A5%E5%8E%86%E3%80%82%3C%2Fspan%3E%0A%0A%60%60%60mermaid%0Aflowchart%20TD%0A%20%20D%5B%22%E7%BC%BA%E9%99%B7%E5%AF%86%E5%BA%A6%20D%22%5D%20--%3E%20POI%5B%22Poisson%20Y%3De%5E%7B-DA%7D%22%5D%0A%20%20A%5B%22%E6%9C%89%E6%95%88%E9%9D%A2%E7%A7%AF%20A%22%5D%20--%3E%20POI%0A%20%20CL%5B%22%E8%81%9A%E7%B1%BB%20%2F%20D%20%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20NB%5B%22%E8%B4%9F%E4%BA%8C%E9%A1%B9%22%5D%0A%20%20POI%20--%3E%20FIT%5B%22%E6%8E%A2%E9%92%88%E5%9B%BE%E6%8B%9F%E5%90%88%22%5D%0A%20%20NB%20--%3E%20FIT%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[2]||(E[2]=A('<p>Poisson 是独立均匀的基线；空间相关应先拆系统，再对残差拟合聚类。倒推 \\(D\\) 不能直接拧扫描机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型不区分桥连来自 OPC 还是颗粒。不发明新 arXiv。不把某厂 \\(D\\) 数字当公开规格。</p><p>后课默认：随机颗粒可用 Poisson/负二项做账；布局灵敏度用关键面积。下一课把 \\(A\\) 从芯片面积改成关键面积。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Poisson 是独立均匀缺陷的基线；簇生用负二项。</li><li>倒推 \\(D\\) 不能直接当光刻旋钮。</li><li>大管芯与边缘管芯要分层拟合。</li><li>拟合前先做系统叠图，相关残差再进负二项。</li><li>出处：Stapper 良率与负二项；半导体良率教材通称。</li></ul>',6))])}const _=s(C,[["render",D]]);export{c as __pageData,_ as default};
